<script setup lang="ts">
import {computed} from 'vue';import {useRoute,useRouter} from 'vue-router';import {admin,clearAuth,isDemo} from '../../shared/api';import {ElMessage} from 'element-plus';import {isStaff,managementAccount} from './access'
// 接待导航只展示日常工作入口，经营配置保留在店长后台。
const route=useRoute(),router=useRouter(),nav=computed(()=>isStaff.value?[['/','接待工作台'],['/orders','预约与交付'],['/pets','宠物档案'],['/security','账号安全']]:[['/','经营工作台'],['/employees','员工管理'],['/pets','宠物管理'],['/orders','预约与订单'],['/after-sales','售后处理'],['/community','社区管理'],['/knowledge','知识库'],['/ai-statistics','AI 统计'],['/agreements','协议管理'],['/shop','门店设置'],['/security','账号安全']])
async function logout(){try{await admin('POST','/admin/auth/logout');clearAuth('admin');await router.replace('/login')}catch(e){ElMessage.error(e instanceof Error?e.message:'退出失败')}}
</script>
<template><RouterView v-if="route.path==='/login'"/><div v-else class="admin-shell"><aside class="sidebar"><RouterLink to="/" class="brand">暖爪</RouterLink><p class="console-label">STORE CONSOLE</p><nav aria-label="管理导航"><RouterLink v-for="item in nav" :key="item[0]" :to="item[0]" :class="{active:route.path===item[0]||(item[0]!=='/'&&route.path.startsWith(item[0]))}">{{item[1]}}</RouterLink></nav><div class="sidebar-bottom"><p>单店自营<br>{{managementAccount?.displayName||managementAccount?.username}} · {{isStaff?'接待员工':'店长'}}</p><button @click="logout">退出登录</button></div></aside><div class="admin-body"><header class="admin-header"><h1>{{route.path==='/'?(isStaff?'接待工作台':'经营工作台'):route.meta.title}}</h1><span>{{new Date().toLocaleDateString('zh-CN')}}</span></header><main><RouterView :key="route.path"/></main></div></div><div v-if="isDemo" class="admin-demo">演示环境 · 本地示例数据 · 不调用真实支付、短信或 AI 服务</div></template>
